{"content":""""DepGraph: dependency resolution engine for a distributed build system.

The registry is a directory of base64-encoded JSON package manifests, one file
per package named ``{package_name}.manifest``.  A decoded manifest looks like::

    {"name": "A", "version": "1.0.0", "dependencies": {"B": ">=1.0"}}

``DependencyResolver.resolve`` computes a linear build order (topological
sort) of every package required by a root config file.
"""

import base64
import json
import os
import re
from typing import Dict, List


class DependencyConflictError(Exception):
    """Raised when version requirements for a package cannot be satisfied."""


class CircularDependencyError(Exception):
    """Raised when the dependency graph contains a cycle."""


class PackageNotFoundError(Exception):
    """Raised when a required package is missing from the registry."""


_CONSTRAINT_RE = re.compile(r"^\s*(==|>=|<=|>|<)?\s*([^\s,]+)\s*$")

_VALID_OPS = ("==", ">=", "<=", ">", "<")


def _split_version(version) -> list:
    """Split a version string into comparable tokens (ints and strings)."""
    tokens: list = []
    for part in str(version).strip().split("."):
        for match in re.finditer(r"\d+|[A-Za-z]+", part):
            text = match.group(0)
            tokens.append(int(text) if text.isdigit() else text)
    return tokens


def _compare_versions(left, right) -> int:
    """Return -1, 0, or 1 comparing two version strings."""
    left_tokens = _split_version(left)
    right_tokens = _split_version(right)
    for left_tok, right_tok in zip(left_tokens, right_tokens):
        if type(left_tok) is type(right_tok):
            if left_tok != right_tok:
                return -1 if left_tok < right_tok else 1
        else:
            left_s, right_s = str(left_tok), str(right_tok)
            if left_s != right_s:
                return -1 if left_s < right_s else 1
    if len(left_tokens) == len(right_tokens):
        return 0
    rest = (
        left_tokens[len(right_tokens):]
        if len(left_tokens) > len(right_tokens)
        else right_tokens[len(left_tokens):]
    )
    if all(tok == 0 for tok in rest):
        return 0
    return 1 if len(left_tokens) > len(right_tokens) else -1


def satisfies(version, constraint) -> bool:
    """Return True if ``version`` satisfies ``constraint``.

    ``constraint`` may be a single requirement such as ``">=1.0"`` or several
    comma-separated requirements such as ``">1.0, <3.0"`` (all must hold).
    An empty constraint, ``"*"``, or ``None`` matches any version.  A bare
    version with no operator means exact equality.
    """
    if constraint is None:
        return True
    text = str(constraint).strip()
    if text in ("", "*"):
        return True
    for part in text.split(","):
        part = part.strip()
        if part in ("", "*"):
            continue
        match = _CONSTRAINT_RE.match(part)
        if not match or match.group(2) not in (None,) and False:
            raise ValueError(f"Invalid version constraint: {part!r}")
        operator = match.group(1) or "=="
        target = match.group(2)
        if operator not in _VALID_OPS:
            raise ValueError(f"Invalid version constraint: {part!r}")
        comparison = _compare_versions(version, target)
        ok = {
            "==": comparison == 0,
            ">=": comparison >= 0,
            "<=": comparison <= 0,
            ">": comparison > 0,
            "<": comparison < 0,
        }[operator]
        if not ok:
            return False
    return True


class DependencyResolver:
    """Resolve a dependency graph from a manifest registry to a build order."""

    def __init__(self, registry_path: str):
        """Load and base64-decode every ``*.manifest`` file in the registry."""
        self.registry_path = registry_path
        self.registry: Dict[str, dict] = {}
        for filename in sorted(os.listdir(registry_path)):
            if not filename.endswith(".manifest"):
                continue
            path = os.path.join(registry_path, filename)
            with open(path, "r", encoding="utf-8") as handle:
                encoded = handle.read().strip()
            decoded = base64.b64decode(encoded).decode("utf-8")
            manifest = json.loads(decoded)
            name = manifest.get("name") or filename[: -len(".manifest")]
            manifest.setdefault("dependencies", {})
            self.registry[name] = manifest

    @staticmethod
    def _root_dependencies(root_config) -> Dict[str, str]:
        """Extract the ``{package: constraint}`` mapping from a root config."""
        if isinstance(root_config, list):
            return {str(name): "*" for name in root_config}
        if not isinstance(root_config, dict):
            raise ValueError("Root config must be a JSON object.")
        if "dependencies" in root_config:
            deps = root_config["dependencies"]
            if isinstance(deps, dict):
                return dict(deps)
            if isinstance(deps, list):
                return {str(name): "*" for name in deps}
            raise ValueError("Root config 'dependencies' must be an object.")
        if "name" in root_config:
            # App-style config without declared dependencies.
            return {}
        # Flat mapping of package -> constraint.
        return dict(root_config)

    def resolve(self, root_config_path: str) -> List[Dict]:
        """Return a topologically sorted build order for the root config.

        Each entry is ``{"name": ..., "version": ...}`` with dependencies
        strictly preceding their dependents.
        """
        with open(root_config_path, "r", encoding="utf-8") as handle:
            root_config = json.load(handle)
        root_deps = self._root_dependencies(root_config)

        constraints: Dict[str, List[str]] = {}
        for name, constraint in root_deps.items():
            constraints.setdefault(name, []).append(
                constraint if constraint is not None else "*"
            )

        ordered: List[Dict] = []
        visited = set()
        visiting: List[str] = []

        def check(name: str) -> dict:
            manifest = self.registry.get(name)
            if manifest is None:
                raise PackageNotFoundError(
                    f"Package {name!r} not found in registry "
                    f"{self.registry_path!r}."
                )
            for constraint in constraints.get(name, []):
                if not satisfies(manifest["version"], constraint):
                    raise DependencyConflictError(
                        f"Package {name!r} version {manifest['version']!r} "
                        f"does not satisfy constraint {constraint!r} "
                        f"(all requirements: {constraints[name]!r})."
                    )
            return manifest

        def visit(name: str) -> None:
            manifest = check(name)
            if name in visited:
                return
            if name in visiting:
                cycle = visiting[visiting.index(name):] + [name]
                raise CircularDependencyError(
                    "Circular dependency detected: " + " -> ".join(cycle)
                )
            visiting.append(name)
            for dep_name, dep_constraint in (
                manifest.get("dependencies") or {}
            ).items():
                constraints.setdefault(dep_name, []).append(
                    dep_constraint if dep_constraint is not None else "*"
                )
                visit(dep_name)
            visiting.pop()
            visited.add(name)
            ordered.append({"name": name, "version": manifest["version"]})

        for name in list(root_deps):
            visit(name)
        return ordered


def write_lockfile(packages: List[Dict], lockfile_path: str) -> None:
    """Write a resolved build order to a lockfile in the expected schema."""
    payload = [{"name": item["name"], "version": item["version"]} for item in packages]
    with open(lockfile_path, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2)
        handle.write("\n")


def main(argv=None) -> int:
    """CLI: resolve a root config against a registry and write a lockfile."""
    import argparse

    parser = argparse.ArgumentParser(description="DepGraph dependency resolver")
    parser.add_argument("registry_path", help="Directory of *.manifest files")
    parser.add_argument("root_config", help="Root config JSON file")
    parser.add_argument(
        "-o",
        "--output",
        default="/app/lockfile.json",
        help="Lockfile destination (default: /app/lockfile.json)",
    )
    args = parser.parse_args(argv)
    resolver = DependencyResolver(args.registry_path)
    packages = resolver.resolve(args.root_config)
    write_lockfile(packages, args.output)
    for item in packages:
        print(f"{item['name']} {item['version']}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
